#!/usr/bin/env python3
"""Minimal QMP client. Usage:
  qmp.py [addr] <command> [args]
  e.g.: qmp.py query-status
         qmp.py sendkey l w i n ret
         qmp.py tcp:127.0.0.1:4444 query-status
Default addr: unix:/tmp/qmp-win311.sock
"""
import socket, sys, json

class QMP:
    def __init__(self, addr):
        if addr.startswith('unix:'):
            self.s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
            self.s.connect(addr[5:])
        else:
            host, port = addr.rsplit(':', 1)
            self.s = socket.socket()
            self.s.connect((host, int(port)))
        self.buf = b''
        self._read_greeting()
        self.cmd('qmp_capabilities')

    def _readline(self):
        while b'\n' not in self.buf:
            d = self.s.recv(65536)
            if not d:
                raise EOFError('QMP connection closed')
            self.buf += d
        line, self.buf = self.buf.split(b'\n', 1)
        return line

    def _read_greeting(self):
        while True:
            line = self._readline()
            try:
                msg = json.loads(line)
            except Exception:
                continue
            if isinstance(msg, dict) and 'QMP' in msg:
                return

    def cmd(self, name, **args):
        payload = {'execute': name}
        if args:
            payload['arguments'] = args
        self.s.sendall((json.dumps(payload) + '\n').encode())
        while True:
            line = self._readline()
            try:
                msg = json.loads(line)
            except Exception:
                continue
            if not isinstance(msg, dict):
                continue
            if 'error' in msg:
                raise RuntimeError('QMP error: %s' % msg['error'])
            if 'return' in msg:
                return msg['return']

if __name__ == '__main__':
    argv = sys.argv[1:]
    addr = 'unix:/tmp/qmp-win311.sock'
    if argv and not argv[0].startswith('query-') and argv[0] not in (
            'sendkey', 'cont', 'stop', 'system_powerdown', 'screendump'):
        addr, argv = argv[0], argv[1:]
    q = QMP(addr)
    name = argv[0]
    if name == 'sendkey':
        result = q.cmd('sendkey', keys=argv[1:])
    else:
        result = q.cmd(name)
    print(json.dumps(result))

